class EmbedTrackedScalarFieldCriticalPoints(Node):

    def __init__(self, parent_node_id : str, radius : float = 3.0):
        if correctness_checks_on():
            if radius <= 0:
                raise Exception(f"Radius must be positive, yet the radius specified was {radius}.")

        super().__init__(parent_node_id, types.TrackedScalarCriticalPoints, types.TrackedScalarCriticalPointsEmbedding, locals(), True, True)

        self.radius = radius

    @classmethod
    def chat_description(cls):
        return "queued embedding the tracked scalar field critical points"

    @classmethod
    def description(cls):
        return 'Creates a geometric embedding of a set of tracked scalar field critical points.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'A node of type tracked_scalar_cp corresponding to the tracked '
                           'critical points to visualize.',
         'radius': 'The radius to use for the visualization.'}

    def compatible_to_visualize(self, other):
        if issubclass(other.node_type, types.ScalarCriticalPointsEmbedding) and \
           self.parent_node.parent_node_id == other.parent_node_id:

            return False, "Cannot visualize a scalar field's set of critical points both tracked and "\
                          "untracked at the same time. They will overlap."

        return True, ""

